// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testRegression_property() public {
        address token = address(new MinimalERC721());
        MinimalERC721(token).mint(address(this), 1);

        MinimalERC721(token).safeTransferFrom(address(this), address(c), 1);

        bool available = c.availableForFlashLoan(token, 1);
        assertTrue(available);
    }
}

contract MinimalERC721 {
    mapping(uint256 => address) public _ownerOf;
    mapping(address => uint256) public _balanceOf;

    function mint(address to, uint256 id) external {
        _ownerOf[id] = to;
        _balanceOf[to]++;
    }

    function safeTransferFrom(address from, address to, uint256 id) external {
        require(_ownerOf[id] == from, "wrong from");
        _ownerOf[id] = to;
        _balanceOf[from]--;
        _balanceOf[to]++;
        if (to.code.length > 0) {
            (bool success, bytes memory data) = to.call(
                abi.encodeWithSelector(
                    bytes4(keccak256("onERC721Received(address,address,uint256,bytes)")),
                    msg.sender, from, id, ""
                )
            );
            require(success && data.length == 32 && abi.decode(data, (bytes4)) == bytes4(keccak256("onERC721Received(address,address,uint256,bytes)")), "unsafe recipient");
        }
    }

    function ownerOf(uint256 id) external view returns (address) {
        return _ownerOf[id];
    }
}
